    union {
        struct {
            uint32_t parent_stream_id;
            unsigned promise_sent : 1;
        } push;
        struct {
            unsigned casper_is_ready : 1;
        } pull;
    };
    unsigned blocked_by_server : 1;
    /**
     * if the response body is streaming
     */
    unsigned _conn_stream_in_progress : 1;
